examples.code:
[X, Y, Z] = meshgrid(linspace(-1, 1, 12));
V = sqrt(X.^2 + Y.^2 + (Z + 0.6).^2);
fv = isosurface(X, Y, Z, V, 1);
size(fv.faces, 1)
p = patch(fv, 'FaceColor', [0.8 0.4 0.2], 'EdgeColor', 'none');
isonormals(X, Y, Z, V, p)
fvc = isocaps(X, Y, Z, V, 1, 'below');
patch(fvc, 'FaceColor', 'interp', 'EdgeColor', 'none')
view(3), axis equal, camlight, lighting gouraud

[X, Y, Z] = meshgrid(linspace(-2, 2, 20));
V = X.*exp(-X.^2 - Y.^2 - Z.^2);
subplot(1, 2, 1), slice(X, Y, Z, V, [-1 0.8], 2, -2), shading flat, view(-35, 25)
subplot(1, 2, 2), contourslice(X, Y, Z, V, [], [], [-1 0 1], 8), view(-35, 25)

rng default
[X, Y, Z] = meshgrid(1:20);
V = double((X - 10).^2 + (Y - 10).^2 + (Z - 10).^2 < 49) + 0.3*rand(20, 20, 20);
W = smooth3(V, 'gaussian', 5);
size(reducevolume(W, 2))
size(subvolume(W, [1 10 NaN NaN 5 15]))
volumebounds(X, Y, Z, W)
fv = isosurface(X, Y, Z, W, 0.6);
r = reducepatch(fv, 0.25);
[size(fv.faces, 1), size(r.faces, 1)]
patch(shrinkfaces(r, 0.6), 'FaceColor', [0.3 0.6 0.9]), view(3), axis equal

[X, Y] = meshgrid(linspace(0, 2, 20));
U = X; V = -Y;
XY = stream2(X, Y, U, V, 0.1*ones(1, 5), linspace(0.4, 2, 5));
numel(XY)
subplot(1, 2, 1), streamline(XY), hold on, streamparticles(XY, 15), hold off, axis equal
[X, Y] = meshgrid(linspace(-1, 1, 20));
subplot(1, 2, 2), streamslice(X, Y, -Y, X), axis equal

[X, Y, Z] = meshgrid(linspace(-1, 1, 10), linspace(-1, 1, 10), linspace(0, 1, 8));
U = -Y; V = X; W = 0.3*ones(size(X));
[cx, cy, cz] = meshgrid([-0.6 0 0.6], [-0.6 0 0.6], 0.5);
subplot(1, 2, 1), coneplot(X, Y, Z, U, V, W, cx, cy, cz, 1), axis equal, view(3)
subplot(1, 2, 2), streamribbon(X, Y, Z, U, V, W, [0.5 -0.5], [0 0], [0 0]), axis equal, view(3)
hold on, streamtube(X, Y, Z, U, V, W, 0, 0.5, 0), hold off

[X, Y] = meshgrid(linspace(-1, 1, 15));
Z = 1 - X.^2 - Y.^2;
[Nx, Ny, Nz] = surfnorm(X, Y, Z);
[Nx(8, 8), Ny(8, 8), Nz(8, 8)]
D = diffuse(Nx, Ny, Nz, [1 0 1]);
S = specular(Nx, Ny, Nz, [1 0 1], [0 0 1]);
subplot(1, 2, 1), surfnorm(X, Y, Z), axis equal
subplot(1, 2, 2), surf(X, Y, Z, D + S), shading interp, axis equal, colorbar
